/**
 * First-run sandbox-setup nudge (#1916). Under the deny-list posture (auto-run), the OS sandbox is the
 * layer that actually confines Bash — but on a fresh machine it isn't installed yet. When the posture
 * is on and the probe (#1982) says the sandbox isn't ready, surface a one-time, dismissible nudge that
 * does the install **right here**: the step's action button (Install bubblewrap on Linux / Install
 * sandbox on Windows) runs `provision_sandbox` with a live progress bar, via the shared
 * `useSandboxReadiness` hook (same engine as the Settings posture card). It auto-hides once the
 * sandbox is ready or the user switches to the allow-list posture. A step the app can't auto-install
 * (e.g. WSL not present) shows the manual next step from the probe's `detail` instead of a dead button.
 *
 * It SELF-LIMITS by counting DISMISSALS: each ✕ press bumps the persisted `sandboxNudgeDismissCount`,
 * and once that reaches `SANDBOX_NUDGE_MAX_DISMISSALS` the nudge stays hidden across launches. Counting
 * dismissals (not shows) keeps the nudge visible on every launch until the user actually acknowledges
 * it, rather than vanishing after one render they may have missed. (Settings still surfaces the same
 * install action permanently, so the user can always set it up there.)
 */
const SANDBOX_NUDGE_MAX_DISMISSALS = 1;

export function SandboxSetupBanner() {
  const bypassPermissions = useAppStore((s) => s.bypassPermissions);
  const dismissCount = useAppStore((s) => s.sandboxNudgeDismissCount);
  const dismiss = useAppStore((s) => s.dismissSandboxNudge);
  const { sandbox, installing, installMsg, install } = useSandboxReadiness();

  if (dismissCount >= SANDBOX_NUDGE_MAX_DISMISSALS || !bypassPermissions || !sandbox || sandbox.ready) return null;

  const label = sandbox.needsWsl ? "Install sandbox" : "Install bubblewrap";
  return (
    <Banner
      variant="bar"
      tone="warn"
      lead={<ShieldAlert size={14} style={{ color: "var(--warn)", flexShrink: 0 }} />}
      right={
        sandbox.autoInstallable ? (
          <Button variant="primary" onClick={install} disabled={installing}>
            {installing ? "Installing…" : label}
          </Button>
        ) : undefined
      }
      onDismiss={dismiss}
    >
      <Stack gap={4} style={{ flex: 1, minWidth: 0 }}>
        <Text>
          <b>Agent sandbox not set up</b> — {installing ? "installing…" : (installMsg ?? sandbox.detail)}
        </Text>
        {installing && (
          <Box aria-hidden bg="color-mix(in oklch, var(--warn), transparent 75%)" radius={2} style={{ height: 3, overflow: "hidden" }}>
            <Box bg="var(--warn)" style={{ height: "100%", width: "30%", animation: "scan 1.1s linear infinite" }} />
          </Box>
        )}
      </Stack>
    </Banner>
  );
}

/**
 * Application-complete banner (#2619). When the active project's FLEET has finished — it has planned
 * issues and EVERY one is done (`complete`/`verified`, {@link projectComplete}) — announce it, so the
 * user knows the build landed and can do a verify/preview run. Polls the active project's plan.db
 * issues only while it HAS a fleet and hasn't been acknowledged this session (so it never nags a
 * still-building or already-seen project). The CTA opens the finished project — the entry point the
 * verify preview + reviewer loop (#…) will grow into. Acknowledging (✕ or the CTA) hides it for the
 * session, keyed per project so a different project can still announce its own completion.
 */
const COMPLETE_POLL_MS = 20000;

function ProjectCompleteBanner() {
  const activeProjectId = useAppStore((s) => s.activeProjectId);
  const activeProjectName = useAppStore((s) => s.activeProjectName);
  const planFleet = useAppStore((s) => s.planFleet);
  const navigate = useAppStore((s) => s.navigate);
  const [acked, setAcked] = useState<Set<string>>(() => new Set());
  const [completeKey, setCompleteKey] = useState<string | null>(null);

  const key = activeProjectId ?? "";
  // Only a project that was actually BUILT (has a fleet) and hasn't been acknowledged this session.
  const enabled = !!key && (planFleet[key]?.streams.length ?? 0) > 0 && !acked.has(key);

  usePoll(async (isCancelled) => {
    if (!enabled) return;
    // Shared with the Glance readers of the same list (#five-callers-one-spawn-for-the-same-plan-read):
      // this banner polls on the same 20s cadence, so a reading from inside that window is exactly as
      // fresh as the one it would have launched a process for.
      const issues = await bscJsonShared<PlanIssue[]>(key, ["plan", "list", "--full", "--json"], [], COMPLETE_POLL_MS);
    if (isCancelled()) return;
    setCompleteKey(projectComplete(issues) ? key : null);
  }, COMPLETE_POLL_MS, [enabled, key]);

  const ack = useCallback((k: string) => setAcked((s) => new Set(s).add(k)), []);

  if (!enabled || completeKey !== key) return null;
  const name = activeProjectName || key;

  return (
    <Banner
      variant="bar"
      tone="accent"
      role="status"
      lead={<PartyPopper size={15} style={{ color: "var(--accent)", flexShrink: 0 }} />}
      onDismiss={() => ack(key)}
      right={
        <Button
          variant="primary"
          style={{ display: "inline-flex", alignItems: "center", gap: 6 }}
          onClick={() => { navigate({ workspace: "glance", page: "network", drill: key }); ack(key); }}
        >
          Preview &amp; review
        </Button>
      }
    >
      <Box as="span" style={{ flex: 1, minWidth: 0 }}>
        <b>{name} is complete</b> — every planned issue landed. Preview and review your app.
      </Box>
    </Banner>
  );
}

/**
 * The app-shell alerts, floated in a FIXED top-right overlay (`.app-banner-stack`) so they never push
 * the shell down or cram the UI. Each adapter gates its own visibility (an empty stack is inert —
 * `pointer-events: none`). Multi-item alerts (quarantine, session recovery) collapse to ONE summary
 * banner with a "Review" drawer rather than one bar per item. Mounted once by App.
 */
/** Where the bsc-on-PATH dismissal persists (a nudge, not a nag). */
const PATH_DISMISS_KEY = "bsc.pathExpose.dismissed";

/**
 * bsc-on-PATH banner (#2734). Inside the app, sessions exec the bundled `bsc` by an absolute `$BSC_BIN`
 * path (#2001) — no PATH. So a bare `bsc` in the user's OWN terminal won't resolve. When detection
 * (`path_expose_status`) reports it isn't on PATH, this offers a one-click, CONSENTED add: the banner
 * names the exact dir first, the click IS the consent, and `path_expose_configure` reports back exactly
 * what changed + how to undo it. Dismissal persists; once configured, detection hides it next launch.
 */
export function PathExposeBanner() {
  const [status, setStatus] = useState<{ configured: boolean; binDir: string | null } | null>(null);
  const [dismissed, setDismissed] = useState(() => {
    try { return localStorage.getItem(PATH_DISMISS_KEY) === "1"; } catch { return false; }
  });
  const [busy, setBusy] = useState(false);
  const [done, setDone] = useState<{ target: string; undo: string } | null>(null);
  const [error, setError] = useState("");

  useEffect(() => {
    let cancelled = false;
    // Fall back to "configured" on any detection failure — never nag when we can't actually tell.
    void safeInvoke<{ configured: boolean; binDir: string | null }>(
      "path_expose_status", undefined, { configured: true, binDir: null },
    ).then((s) => { if (!cancelled) setStatus(s); });
    return () => { cancelled = true; };
  }, []);

  const dismiss = () => {
    try { localStorage.setItem(PATH_DISMISS_KEY, "1"); } catch { /* private mode — dismiss for this run */ }
    setDismissed(true);
  };

  const configure = async () => {
    setBusy(true);
    setError("");
    try {
      const r = await invoke<{ changed: boolean; target: string; undo: string }>("path_expose_configure");
      setDone({ target: r.target, undo: r.undo });
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setBusy(false);
    }
  };

  // Nothing to offer: still probing, already on PATH, no bundled bsc, or dismissed.
  if (dismissed || !status || status.configured || !status.binDir) return null;

  if (done) {
    return (
      <Banner
        variant="bar"
        tone="success"
        onDismiss={dismiss}
        lead={<Text weight={600} style={{ whiteSpace: "nowrap" }}>✓ bsc on PATH</Text>}
      >
        <Text>
          Added to {done.target}. Reopen your terminal to run <Text as="span" mono>bsc</Text>. To undo: {done.undo}
        </Text>
      </Banner>
    );
  }

  return (
    <Banner
      variant="bar"
      tone="info"
      onDismiss={dismiss}
      lead={<Text weight={600} style={{ whiteSpace: "nowrap" }}>bsc CLI</Text>}
      right={
        <Button variant="primary" onClick={configure} disabled={busy}>
          {busy ? "Configuring…" : "Add to PATH"}
        </Button>
      }
    >
      <Stack gap={2} style={{ flex: 1 }}>
        <Text>
          Run <Text as="span" mono>bsc</Text> from your own terminal — add{" "}
          <Text as="span" mono>{status.binDir}</Text> to your PATH.
        </Text>
        {error && <Text size="xxs" style={{ color: "var(--danger)" }}>{error}</Text>}
      </Stack>
    </Banner>
  );
}

const KIT_CLASS_TONE: Record<KitChange["class"], string> = {
  breaking: "var(--danger)",
  additive: "var(--accent)",
  fix: "var(--success)",
};

/**
 * Kit-change approval banner (#2944). After the designer session makes kit modifications, the store
 * fans them out to consumer projects (`kitDispatches`). By default (auto-apply OFF — a Planner setting)
 * they're GATED here: one summary banner + a Review drawer listing each change, its propagated
 * consumers. Hidden entirely when auto-apply is ON.
 *
 * NOTICE, NOT A CONTROL (#app-stops-pushing-prompts). It used to carry an **Approve** button that
 * delivered the change into each live consumer's director by typing into that session. The app does not
 * push prompts any more — not even behind a click — so approval is gone and only Dismiss remains. A kit
 * change is adopted by the DIRECTOR reading the queue on its own cadence, the same way every other duty
 * moved to polling under this directive.
 */
function KitChangesBanner() {
  const dispatches = useAppStore((s) => s.kitDispatches);
  const autoApply = useAppStore((s) => s.autoApplyKitChanges);
  const dismissKitChange = useAppStore((s) => s.dismissKitChange);
  const [open, setOpen] = useState(false);

  // Group the pending dispatches by change → its consumer projects.
  const groups = useMemo(() => {
    const m = new Map<string, { change: KitChange; projects: string[] }>();
    for (const d of dispatches) {
      const g = m.get(d.change.id);
      if (g) g.projects.push(d.projectKey);
      else m.set(d.change.id, { change: d.change, projects: [d.projectKey] });
    }
    return [...m.values()];
  }, [dispatches]);

  if (autoApply || groups.length === 0) return null;
  const n = groups.length;
  const dismissChange = (g: { change: KitChange; projects: string[] }) => dismissKitChange(g.change.id);

  return (
    <>
      <Banner
        variant="bar"
        tone="accent"
        role="status"
        lead={<GitBranch size={14} style={{ color: "var(--accent)", flexShrink: 0 }} />}
        right={<Button onClick={() => setOpen((o) => !o)}>{open ? "Hide" : "Review"}</Button>}
      >
        <Box as="span" style={{ flex: 1, minWidth: 0 }}>
          <b>{n} kit change{n === 1 ? "" : "s"}</b> from the designer {n === 1 ? "is" : "are"} waiting for a director to adopt.
        </Box>
      </Banner>

      {open && (
        <Box className="banner-drawer">
          {groups.map((g) => (
            <Box key={g.change.id} border="soft" radius={6} style={{ overflow: "hidden" }}>
              <Row gap={8} style={{ padding: "7px 10px", flexWrap: "wrap", alignItems: "center" }}>
                <Chip color={KIT_CLASS_TONE[g.change.class]}>{g.change.class}</Chip>
                <Text weight={600} size={12.5}>{g.change.component}</Text>
                <Text size={12} tone="muted" style={{ flex: 1, minWidth: 100 }}>— {g.change.summary}</Text>
                <Button variant="ghost" style={{ fontSize: 11, padding: "3px 8px" }} onClick={() => dismissChange(g)}>Dismiss</Button>
              </Row>
              {g.change.migration && (
                <Text size={11} tone="muted" as="div" style={{ padding: "0 10px 6px" }}>Migration: {g.change.migration}</Text>
              )}
              <Box style={{ padding: "6px 10px", borderTop: "1px solid var(--border-soft)", display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center" }}>
                <Text size={10.5} tone="dim">propagates to</Text>
                {g.projects.length === 0 ? (
                  <Text size={10.5} tone="dim">— no consumer projects yet</Text>
                ) : g.projects.map((pk) => (
                  <Text key={pk} mono size={10.5} tone="muted" style={{ background: "var(--bg-panel)", borderRadius: 4, padding: "1px 6px" }}>{pk}</Text>
                ))}
              </Box>
            </Box>
          ))}
        </Box>
      )}
    </>
  );
}


/**
 * Interrupted-loop banner (#3961). A `bsc loop` in flight when the app DIES is never reconciled: the
 * store keeps it `open`, and a participant's `bsc loop watch` blocks on a turn that will never come.
 * Every other `ended_by` describes a loop that reached a DECISION (a sentinel fired, a ceiling was hit,
 * someone called stop); a crash reaches none of them.
 *
 * Gated on the SAME unclean-shutdown signal as the session restore above — after a clean quit an open
 * loop is legitimately dormant, not stranded.
 *
 * IT REPORTS, IT DOES NOT ASK. The boot path closes them (`bsc loop reap`, recording
 * `ended_by=interrupted` rather than `stop` so the row stays truthful about why it ended), because a
 * loop left open blocks `watch` on a turn that will never come and nothing else ever closes it — a
 * decision with one answer is not a decision to put to a user. What is left here is the fact, which
 * they do want: their counterpart is not coming back, and this is why.
 */
function InterruptedLoopBanner() {
  const loops = useAppStore((s) => s.interruptedLoops);
  const dismiss = useAppStore((s) => s.dismissInterruptedLoops);

  if (loops.length === 0) return null;
  const n = loops.length;
  const named = loops.slice(0, 2).map((l) => `${l.a}↔${l.b}`).join(", ");

  return (
    <Banner variant="bar" tone="warn" onDismiss={dismiss}>
      {n} loop{n === 1 ? "" : "s"} ({named}{n > 2 ? `, +${n - 2}` : ""}) {n === 1 ? "was" : "were"}{" "}
      <b>interrupted</b> when the app stopped unexpectedly, and {n === 1 ? "has" : "have"} been closed
      — anything that was waiting on a turn is released rather than blocked forever.
    </Banner>
  );
}

/** The verdicts worth a banner. `updated-upstream` — a store copy that differs from its seed — is
 *  deliberately NOT here.
 *
 *  Under store-always-wins the seed is the app's STARTING POINT and the app is edited in place, so
 *  divergence is what a used app looks like, not a fault. Reporting it made the banner read
 *  "301 records differ … review which side is right" — a description of the intended state, climbing with
 *  every edit, drowning the two verdicts that actually need a person.
 *
 *  `reset-to-seed` is unreachable today (no caller passes `seedAuthoritative` any more) but stays in the
 *  set: if it is ever re-enabled it means a store copy was OVERWRITTEN, which is the most actionable
 *  verdict there is. A banner that would silently miss that is worse than one carrying a dead branch.
 *
 *  `refreshed` is that same event on the branch that IS reachable
 *  (#a-reseed-must-not-silently-overwrite-a-designer-edit): the packaged copy replaced the store copy.
 *  It fires only when the content actually differed, so a stamp-only correction stays quiet. This is the
 *  verdict that ate 38 records on 2026-08-14 while reporting nothing at all. */
const ACTIONABLE_SEED_KINDS = new Set(["orphaned", "unstamped", "reset-to-seed", "refreshed"]);

/**
 * Seed-notice banner (#4216) — the reader `seedNotices` never had.
 *
 * `reconcileSeed` computes verdicts and the store collects them; nothing rendered them, because every
 * reference to `seedNotices` lived inside the designs slice itself. The mechanism computed the right
 * answer and dropped it on the floor.
 *
 * Now scoped to {@link ACTIONABLE_SEED_KINDS}: a record the seed RETIRED but the store still holds
 * (`orphaned`), and one sitting outside the reconcile entirely (`unstamped`). Both need a decision;
 * plain divergence does not.
 *
 * Still REPORT-ONLY for `orphaned` — which side is right is a per-record judgement, and a one-click bulk
 * resolve would be the more dangerous bug. `unstamped` is the exception and has a repair, because it
 * adjudicates no content at all.
 */
export function SeedDriftBanner() {
  const allNotices = useAppStore((s) => s.seedNotices);
  const dismissSeedNotice = useAppStore((s) => s.dismissSeedNotice);
  const restampUnstamped = useAppStore((s) => s.restampUnstamped);
  const [open, setOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const [result, setResult] = useState<string | null>(null);

  const repair = useCallback(async () => {
    setBusy(true);
    try {
      const { stamped, deferred } = await restampUnstamped();
      // Still REPORT a deferral rather than folding it into the count — a "re-stamped 38" that silently
      // omitted 6 would read as a complete repair. It cannot fire today: deferral needs a
      // `seedAuthoritative` predicate and `planComponentRestamp` passes none, so `deferred` is always 0.
      // The branch stays because it is the honest reading if that predicate ever returns.
      setResult(
        deferred > 0
          ? `Re-stamped ${stamped}. ${deferred} left alone — the seed is authoritative for ${deferred === 1 ? "it" : "them"}, so stamping would replace what renders.`
          : `Re-stamped ${stamped}.`,
      );
    } finally {
      setBusy(false);
    }
  }, [restampUnstamped]);

  // Filter FIRST, then group — so a run whose only verdicts are plain divergence raises nothing at all
  // rather than an empty expander.
  const notices = useMemo(
    () => allNotices.filter((it) => ACTIONABLE_SEED_KINDS.has(it.kind)),
    [allNotices],
  );

  // Group so the count reads as "what kind of trouble", not just "how many".
  const byKind = useMemo(() => {
    const m = new Map<string, typeof notices>();
    for (const n of notices) m.set(n.kind, [...(m.get(n.kind) ?? []), n]);
    return [...m.entries()];
  }, [notices]);

  if (notices.length === 0) return null;
  const n = notices.length;

  return (
    <>
      <Banner
        variant="bar"
        tone="warn"
        lead={<GitBranch size={14} />}
        right={
          <Button size="sm" variant="ghost" onClick={() => setOpen((v) => !v)}>
            {open ? "Hide" : "Review"}
          </Button>
        }
        // Dismissing acknowledges the whole set for this run; the notices are recomputed on the next
        // hydrate, so this hides a known state rather than resolving it.
        onDismiss={() => notices.forEach((it) => dismissSeedNotice(it.type, it.id))}
      >
        {n} record{n === 1 ? "" : "s"} need{n === 1 ? "s" : ""} a decision —{" "}
        <b>{byKind.map(([kind, items]) => `${items.length} ${kind}`).join(" · ")}</b>. Editing in place
        is expected; these sit outside it.
      </Banner>
      {open && (
        <Box className="app-banner-detail">
          <Stack gap={8}>
            {byKind.map(([kind, items]) => (
              <Stack key={kind} gap={4}>
                <Text size={11} tone="dim" mono>
                  {kind} · {items.length}
                </Text>
                <Row gap={4} wrap>
                  {items.map((it) => (
                    <Chip key={`${it.type}:${it.id}`}>{it.name || it.id}</Chip>
                  ))}
                </Row>
                {kind === "orphaned" && (
                  // Disambiguates from the UNRELATED "orphan" `bsc ui doctor`/`graphHealth` finding
                  // (nothing composes it AND used = 0). This "orphaned" means the packaged SEED for
                  // this id left data/components/app/** — true of a built-in that predates the current
                  // migrated-app-page seed set even while it is heavily composed elsewhere (designer
                  // request #110: `DeployToggle`, composed by 8 other components, showed here only
                  // because its seed was never migrated in).
                  <Text size={11} tone="dim">
                    The packaged SEED for this id is gone — that alone does NOT mean it&apos;s unused. Check{" "}
                    <code>bsc ui used-by &lt;id&gt;</code> or <code>bsc ui doctor</code> (a real graph
                    orphan) before deciding whether to keep it or <code>bsc ui remove</code> it.
                  </Text>
                )}
                {kind === "refreshed" && (
                  // REPORT-ONLY, deliberately — same reason `orphaned` is: which side is right is a
                  // per-record judgement and a one-click bulk revert would make the opposite mistake at
                  // the same scale. What a designer needs here is not a button but the fact that the old
                  // source is not gone: every write records `prevSrc`, which is what made the 38 records
                  // of request #63 recoverable.
                  <Text size={11} tone="dim">
                    The packaged copy replaced yours. The previous source is kept —{" "}
                    <code>bsc ui log &lt;id&gt;</code> shows it, and <code>bsc ui set</code> puts it back.
                  </Text>
                )}
                {kind === "unstamped" && (
                  // The ONE verdict with a safe automatic repair (#4207). The others each need a human to
                  // pick a side; this one does not, because it does not adjudicate content at all — it
                  // restores the record's membership in the reconcile and leaves the content alone.
                  <Row gap={8} align="center">
                    <Button size="sm" variant="ghost" disabled={busy} onClick={repair}>
                      {busy ? "Re-stamping…" : `Re-stamp ${items.length}`}
                    </Button>
                    <Text size={11} tone="dim">
                      {result ??
                        "Marks these as packaged built-ins so seed updates reach them again. Content is not changed."}
                    </Text>
                  </Row>
                )}
              </Stack>
            ))}
          </Stack>
        </Box>
      )}
    </>
  );
}

/**
 * Session-stopped banner (#a-stopped-session-says-why) — a TRANSIENT notice naming each pane that
 * just stopped and why.
 *
 * WHY THIS EXISTS. A worker would go away and the app said nothing. The reason was never missing —
 * Rust reaped the child and knew the exit code, the signal, and whether the cage's launcher had
 * failed before the agent ever ran — it just never left the backend: `pty_exit` carried `()`, and
 * the caged-death notice was written as terminal bytes INTO the pane that was about to be destroyed.
 * Measured on one run: fifteen session endings, nine of them `exit=1` on a single worker, and
 * nothing on screen for any of them.
 *
 * IT DISMISSES ITSELF. This is information, not a decision — there is nothing to approve and nothing
 * to undo — so it must not sit there collecting a click. `STOP_NOTICE_MS` (in `paneStops.ts`) is the
 * whole lifetime, and
 * the LOG is what makes that affordable: every stop is written to the app log whether or not anyone
 * was looking, so the five seconds is a courtesy rather than the only chance to find out.
 *
 * ROUTINE STOPS ARE STILL SHOWN, QUIETLY. A session that finished, or one the user switched off, is
 * `neutral` and reads as an ack rather than an alarm — the alternative is a user who closes a pane
 * and wonders whether the silence means it worked.
 */
function SessionStoppedBanner() {
  const paneStops = useAppStore((s) => s.paneStops);
  // The store only changes when a stop is RECORDED, so nothing would re-render at the moment one
  // expires — the banner would linger until the next unrelated store write. This clock is what makes
  // the notice window real rather than nominal, and it only runs while something is on screen.
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    if (paneStops.length === 0) return;
    const t = setInterval(() => setNow(Date.now()), 500);
    return () => clearInterval(t);
  }, [paneStops.length]);

  const shown = stopsForNotice(paneStops, now);
  if (shown.length === 0) return null;

  // COLLAPSED WHEN THERE IS MORE THAN ONE (`one-stop-banner-per-pane-fills-the-screen`).
  //
  // This used to render one full-width bar PER STOP. The events that end several sessions at once —
  // an app relaunch, a fleet stop, a reaper sweep after the renderer dies — are exactly the ones that
  // produced a wall of bars, so the worst display coincided with the worst moment. This file's own
  // note measured fifteen endings in one run.
  //
  // The three deliberate properties of the old design are kept: routine stops are still SHOWN (a
  // closed pane must not read as unexplained silence), a fault still carries its last words (nothing
  // else in the app has them once the pane is recreated), and the notice still dismisses itself.
  // `stopsForNotice` puts faults first so the row worth reading is never below the fold.
  if (shown.length > 1) {
    const worst = shown.find((s) => isFaultStop(s.reason)) ?? shown[0];
    return (
      <Banner
        variant="bar"
        // The tone of the WORST stop, not of the newest: one failure among five clean closes is still
        // a failure, and toning the group by recency would hide it behind whatever happened last.
        tone={stopTone(worst.reason)}
        dot
        role="status"
        right={<Text tone="muted">{shown.length} panes</Text>}
      >
        <Stack style={{ gap: 2 }}>
          <Text><strong>{stopSummary(shown)}</strong></Text>
          {shown.map((stop) => (
            <Text key={`${stop.paneId}:${stop.at}`} size={12} tone="muted">
              {stop.paneId} — {stopHeadline(stop.reason)}
              {isFaultStop(stop.reason) && (
                <>
                  {" "}
                  <code className="mono" style={{ opacity: 0.85 }}>
                    {stop.lastOutput ?? "(it printed nothing)"}
                  </code>
                </>
              )}
            </Text>
          ))}
        </Stack>
      </Banner>
    );
  }

  return (
    <>
      {shown.map((stop) => (
        <Banner
          key={`${stop.paneId}:${stop.at}`}
          variant="bar"
          tone={stopTone(stop.reason)}
          dot
          role="status"
          right={<Text tone="muted">{stop.paneId}</Text>}
        >
          <Text>
            <strong>{stopHeadline(stop.reason)}</strong>
            {" — "}
            {stop.detail}
            {/* THE LAST WORDS (#a-stopped-session-shows-its-last-words). "The agent exited with
                status 1" is true and not actionable; what it PRINTED on the way out is the answer,
                and nothing else in the app has it once the pane is recreated. Faults only — quoting
                a clean ending is how this becomes noise — and a silent death SAYS it was silent
                rather than rendering an empty quote. */}
            {isFaultStop(stop.reason) && (
              <>
                {" "}
                <code className="mono" style={{ opacity: 0.85 }}>
                  {stop.lastOutput ?? "(it printed nothing)"}
                </code>
              </>
            )}
          </Text>
        </Banner>
      ))}
    </>
  );
}

export function AppBanners() {
  // #54 — a notice dismissed from the CLI is not RENDERED, rather than each banner learning a second way
  // to hide itself. Gating here keeps every banner's own dismiss logic untouched (nine components, several
  // with real internal state) and makes the CLI dismissal total: a banner that never mounts cannot appear
  // in a capture, and cannot half-hide by forgetting to consult a flag.
  const dismissed = useAppStore((s) => s.dismissedNotices);
  const show = (id: string) => !dismissed.includes(id);
  return (
    <Box className="app-banner-stack">
      {show("kit-changes") && <KitChangesBanner />}
      {show("seed-drift") && <SeedDriftBanner />}
      {show("interrupted-loop") && <InterruptedLoopBanner />}
      {show("session-recovery") && <SessionRecoveryBanner />}
      {show("quarantine") && <QuarantineBanner />}
      {show("sandbox-setup") && <SandboxSetupBanner />}
      {show("project-complete") && <ProjectCompleteBanner />}
      {show("path-expose") && <PathExposeBanner />}
      {/* LAST, and never gated by `dismissedNotices`: it dismisses ITSELF after STOP_NOTICE_MS, so a
          CLI dismissal has nothing to act on — and silencing it durably would restore exactly the
          silence this exists to end. */}
      <SessionStoppedBanner />
    </Box>
  );
}
